-- ══════════════════════════════════════════════════════════════════════════════
-- MIGRATION 2026-10-18 — feriados viram REGRA, em três tabelas
--
-- O QUE MUDA. `catalogo.feriados` guardava a DATA de cada feriado, ano a ano. Feriado não é data,
-- é regra: o aniversário da cidade é 25/01 para sempre, e Corpus Christi é Páscoa+60 para sempre.
-- Guardado como data, cada ano era um conjunto novo (50.085 linhas para quatro anos) com validade:
-- virar o ano exigia pagar a fonte de novo. Como regra são 12.569 linhas que valem para qualquer
-- ano — conferido: colapsar os quatro anos e reexpandi-los reproduz 99,9% deles.
--
-- EM PROD a tabela antiga está VAZIA (o DDL foi adiantado na migration de 16/10 e nunca populado),
-- então não há dado a converter: derruba-se e criam-se as três novas, já com o conteúdo.
--
-- IDEMPOTENTE: rodar duas vezes não duplica (as tabelas nascem com IF NOT EXISTS e o seed limpa
-- antes de inserir). Validada em dev como no-op na segunda execução.
--
--   psql "$EASY_DB_URL" -v ON_ERROR_STOP=1 -f docs/projects/axys-easy/schemas/migrations/2026-10-18_feriados_regra.sql
-- ══════════════════════════════════════════════════════════════════════════════

BEGIN;

DROP TABLE IF EXISTS catalogo.feriados;

CREATE TABLE IF NOT EXISTS catalogo.feriados_nacionais (
    fer_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fer_nome        TEXT     NOT NULL,
    fer_dia         SMALLINT,                   -- 1..31  — NULL quando móvel
    fer_mes         SMALLINT,                   -- 1..12  — NULL quando móvel
    fer_pascoa_offset SMALLINT,                 -- dias a partir do Domingo de Páscoa; NULL se fixo
    fer_regra       TEXT     NOT NULL DEFAULT 'FIXO',   -- FIXO | PASCOA | APROXIMADO
    fer_fonte       TEXT     NOT NULL,
    fer_coletado_em DATE     NOT NULL DEFAULT CURRENT_DATE,
    fer_criado_em   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT ck_fer_nac_regra CHECK (fer_regra IN ('FIXO','PASCOA','APROXIMADO')),
    -- ou é dia/mês, ou é deslocamento — nunca os dois, nunca nenhum. Uma linha sem regra seria um
    -- feriado que não acontece em dia nenhum, e ela passaria despercebida.
    CONSTRAINT ck_fer_nac_chave CHECK (
        (fer_pascoa_offset IS NULL     AND fer_dia IS NOT NULL AND fer_mes IS NOT NULL) OR
        (fer_pascoa_offset IS NOT NULL AND fer_dia IS NULL     AND fer_mes IS NULL)),
    CONSTRAINT ck_fer_nac_dia CHECK (fer_dia IS NULL OR fer_dia BETWEEN 1 AND 31),
    CONSTRAINT ck_fer_nac_mes CHECK (fer_mes IS NULL OR fer_mes BETWEEN 1 AND 12),
    -- NULLS NOT DISTINCT: sem isto, duas linhas (NULL, NULL, 60) passariam, porque o UNIQUE normal
    -- trata nulo como sempre diferente — e o feriado entraria duas vezes a cada recarga
    CONSTRAINT uq_fer_nac UNIQUE NULLS NOT DISTINCT (fer_dia, fer_mes, fer_pascoa_offset)
);

CREATE TABLE IF NOT EXISTS catalogo.feriados_estaduais (
    fer_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fer_uf          CHAR(2)  NOT NULL,
    fer_nome        TEXT     NOT NULL,
    fer_dia         SMALLINT,
    fer_mes         SMALLINT,
    fer_pascoa_offset SMALLINT,
    fer_regra       TEXT     NOT NULL DEFAULT 'FIXO',
    fer_fonte       TEXT     NOT NULL,
    fer_coletado_em DATE     NOT NULL DEFAULT CURRENT_DATE,
    fer_criado_em   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT ck_fer_est_regra CHECK (fer_regra IN ('FIXO','PASCOA','APROXIMADO')),
    CONSTRAINT ck_fer_est_chave CHECK (
        (fer_pascoa_offset IS NULL     AND fer_dia IS NOT NULL AND fer_mes IS NOT NULL) OR
        (fer_pascoa_offset IS NOT NULL AND fer_dia IS NULL     AND fer_mes IS NULL)),
    CONSTRAINT ck_fer_est_dia CHECK (fer_dia IS NULL OR fer_dia BETWEEN 1 AND 31),
    CONSTRAINT ck_fer_est_mes CHECK (fer_mes IS NULL OR fer_mes BETWEEN 1 AND 12),
    CONSTRAINT uq_fer_est UNIQUE NULLS NOT DISTINCT (fer_uf, fer_dia, fer_mes, fer_pascoa_offset)
);

CREATE TABLE IF NOT EXISTS catalogo.feriados_municipais (
    fer_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fer_mun_id      INTEGER  NOT NULL REFERENCES catalogo.municipios (mun_id)
                    ON UPDATE CASCADE ON DELETE CASCADE,
    fer_nome        TEXT     NOT NULL,
    fer_dia         SMALLINT,
    fer_mes         SMALLINT,
    fer_pascoa_offset SMALLINT,
    fer_regra       TEXT     NOT NULL DEFAULT 'FIXO',
    fer_fonte       TEXT     NOT NULL,
    fer_coletado_em DATE     NOT NULL DEFAULT CURRENT_DATE,
    fer_criado_em   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT ck_fer_mun_regra CHECK (fer_regra IN ('FIXO','PASCOA','APROXIMADO')),
    CONSTRAINT ck_fer_mun_chave CHECK (
        (fer_pascoa_offset IS NULL     AND fer_dia IS NOT NULL AND fer_mes IS NOT NULL) OR
        (fer_pascoa_offset IS NOT NULL AND fer_dia IS NULL     AND fer_mes IS NULL)),
    CONSTRAINT ck_fer_mun_dia CHECK (fer_dia IS NULL OR fer_dia BETWEEN 1 AND 31),
    CONSTRAINT ck_fer_mun_mes CHECK (fer_mes IS NULL OR fer_mes BETWEEN 1 AND 12),
    CONSTRAINT uq_fer_mun UNIQUE NULLS NOT DISTINCT (fer_mun_id, fer_dia, fer_mes, fer_pascoa_offset)
);

-- a consulta é sempre "o que afeta ESTE município", e a UF vem do próprio município
CREATE INDEX IF NOT EXISTS ix_fer_mun_id ON catalogo.feriados_municipais (fer_mun_id);
CREATE INDEX IF NOT EXISTS ix_fer_est_uf ON catalogo.feriados_estaduais (fer_uf);

-- ── conteúdo: as regras apuradas a partir de 2026-2029 ────────────────────────────────────
TRUNCATE catalogo.feriados_nacionais, catalogo.feriados_estaduais, catalogo.feriados_municipais RESTART IDENTITY;

